import{_ as t,o as n,c as r,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy product acceptance checklist","description":"Updated November 11, 2026 for the lesson-collection GDD.\\nThis document defines planned acceptance; it does not report an implemented or tested build.\\nCurrent authorization is ","frontmatter":{"title":"Chainy product acceptance checklist","description":"Updated November 11, 2026 for the lesson-collection GDD.\\nThis document defines planned acceptance; it does not report an implemented or tested build.\\nCurrent authorization is ","source":"docs/requirements/product-requirements.md","category":"Requirements","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/requirements/product-requirements.md","filePath":"content/docs/requirements/product-requirements.md"}'),i={name:"content/docs/requirements/product-requirements.md"};function a(s,e,c,d,l,p){return n(),r("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-product-acceptance-checklist">Chainy product acceptance checklist<a class="header-anchor" href="#chainy-product-acceptance-checklist" aria-label="Link to this section">​</a></h1><p>Updated November 11, 2026 for the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a>. This document defines planned acceptance; it does not report an implemented or tested build. <strong>Current authorization is documentation and setup only; final owner approval is required before Unity development.</strong> The <a href="/Chainy-Docs/content/docs/project-baseline.html">baseline</a> records decisions and the <a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">execution plan</a> records the approval boundary.</p><h2 id="current-acceptance-map">Current acceptance map<a class="header-anchor" href="#current-acceptance-map" aria-label="Link to this section">​</a></h2><p>Use the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html#12-design-acceptance-cases">GDD&#39;s LC-G acceptance cases</a> as the single detailed gameplay checklist. The map below identifies evidence needed later without duplicating its lesson route or minigame rules.</p><table><thead><tr><th>Area</th><th>Intended outcome</th><th>Later evidence</th></tr></thead><tbody><tr><td>World access and orientation</td><td>Main menu opens world selection; Web3, Blockchain, and AI unlock sequentially; each island has a remembered first-visit tutorial</td><td>New-profile, returning-profile, and locked-world checks</td></tr><tr><td>Lesson collection</td><td>Each world has 13 ordered source lessons, totaling 39; collecting an entry activates only its next lesson</td><td>Source coverage, out-of-order interaction, and duplicate-record checks</td></tr><tr><td>Minigames</td><td>Exactly three distinct minigames per world, nine total, entered through ordered item/NPC/facility prerequisites in separate scenes</td><td>Each activity&#39;s success, wrong action, retry, exit, and return checks</td></tr><tr><td>Encyclopedia and required review</td><td>All 13 entries open the required review; its approved completion rule controls world completion and the next unlock</td><td>Collection/quiz state checks, including abandonment and replay</td></tr><tr><td>Offline progress</td><td>SQLite keeps profile-specific progress consistent across scenes, failed saves, and relaunch</td><td>Named-build recovery and two-synthetic-profile results</td></tr><tr><td>Usability and teaching accuracy</td><td>Touch controls and feedback work on the reference phone; essential information works without sound or color; AI simulations are labeled</td><td>Actual device observations and content review</td></tr><tr><td>Delivery and school evidence</td><td>Honest scope statement, manuscript, approved evidence, and rehearsed recovery for the November 21 pre-final</td><td>Build/device records, limitations, actual school guidance, and demonstration evidence</td></tr></tbody></table><p>World sequencing, 39 lessons, nine minigames, and required quizzes are confirmed design direction. The owner confirmed 13 required questions per world, one per lesson, with retries until all mistakes are corrected. All 13 correct answers and a successful save are required for world completion; first responses remain separate evidence. Completing documentation or setup does not satisfy runtime acceptance.</p><p>The reference device remains Android 10/API 29, 4 GB RAM, 128 GB total storage, and a reported 2.3 GHz octa-core CPU. API 25 is the retained minimum install setting, not proof of compatibility on every device. Keep participant identities, credentials, and signing keys outside project records. The November 10 session is a past scheduled event whose actual outcome must be recorded from evidence. <strong>Pre-final remains November 21, 2026.</strong></p><h2 id="historical-requirements">Historical requirements<a class="header-anchor" href="#historical-requirements" aria-label="Link to this section">​</a></h2><p><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/requirements/product-requirements.html#historical-v2-requirements">V2-R01–12 remain in the preserved checklist</a>. They retain their original meanings for old records and are not current implementation tasks. No card is Done merely because its specification or dates changed.</p></div>',1)])])}const m=t(i,[["render",a]]);export{u as __pageData,m as default};
